// [MEDIUM_PRIORITY] PERFORMANCE: String Concatenation optimized
// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.connectivity.toolsimport com.roshan.persona.brain.agentic.AgenticStepResultimport com.roshan.persona.brain.agentic.AgenticToolimport com.roshan.persona.brain.agentic.ToolParamimport com.roshan.persona.brain.context.BrainContextimport kotlinx.coroutines.Dispatchersimport kotlinx.coroutines.withContextimport okhttp3.OkHttpClientimport okhttp3.Requestimport org.json.JSONArrayimport org.json.JSONObjectimport timber.log.Timberimport dagger.Moduleimport dagger.Providesimport dagger.hilt.InstallInimport dagger.hilt.components.SingletonComponentimport dagger.multibindings.IntoSetimport dagger.multibindings.Multibindsimport javax.inject.Singletonimport java.util.concurrent.TimeUnitimport javax.inject.Inject/** * NOUS — Web Search Tool (Module 11 Connectivity → Agentic Tool). * * Strategy §11 + Table 3: Implements the [AgenticTool] interface for web search. * Replaces Brain's placeholder WebSearchTool (which returned "not yet implemented"). * * Uses the DuckDuckGo Instant Answer API (no API key required, privacy-friendly) * as the default search backend. Falls back to HTML scraping if the API returns * no results. * * ## Privacy * * DuckDuckGo doesn't track searches. The query is sent directly to * `https://api.duckduckgo.com/?q=QUERY&format=json` — no intermediary. * PII scrubbing is the caller's responsibility (Brain's pre-processor). * * ## Result Format * * Returns a structured text summary: * ``` * Search results for "latest AI news": * * 1. [Title] — Snippet text... *    Source: https://example.com/article * * 2. [Title] — Snippet text... *    Source: https://example.com/news * ``` * * @see <a href="docs/strategy/NOUS-Strategy-2-14-extracted.txt">§11 Connectivity + Table 3 WebSearchTool</a> */@Singletonclass WebSearchTool @Inject constructor(    private val httpClient: OkHttpClient,) : AgenticTool {    override val id: String = "search_web"    override val displayName: String = "Search Web"    override val description: String =        "Search the web for a query. Use when you need current information or facts you don't know."    override val paramSchema: List<ToolParam> = listOf(        ToolParam(            name = "query",            description = "The search query",            required = true,            example = "latest AI news",        ),    )    override val requiresNetwork: Boolean = true    override suspend fun execute(        params: Map<String, String>,        context: BrainContext,    ): AgenticStepResult {        val startNanos = System.nanoTime()        val query = params["query"] ?: return AgenticStepResult.ToolFailure(            toolId = id,            error = "Missing required parameter: query",            retryable = false,            correlationId = context.correlationId,            durationMs = 0L,        )        return try {            val results = searchDuckDuckGo(query, context)            if (results.isEmpty()) {                AgenticStepResult.ToolSuccess(                    toolId = id,                    output = "No search results found for \"$query\".",                    correlationId = context.correlationId,                    durationMs = (System.nanoTime() - startNanos) / 1_000_000,                )            } else {                val formatted = buildString {                    appendLine("Search results for \"$query\":")                    appendLine()                    results.forEachIndexed { index, result ->                        appendLine("${index + 1}. ${result.title}")                        appendLine("   ${result.snippet}")                        appendLine("   Source: ${result.url}")                        appendLine()                    }                }                AgenticStepResult.ToolSuccess(                    toolId = id,                    output = formatted,                    data = mapOf("results" to results.map { mapOf("title" to it.title, "url" to it.url) }),                    correlationId = context.correlationId,                    durationMs = (System.nanoTime() - startNanos) / 1_000_000,                )            }        } catch (e: Exception) {            Timber.e(e, "Web search failed for query: %s", query)            AgenticStepResult.ToolFailure(                toolId = id,                error = "Search failed: ${e.message}",                retryable = true,                correlationId = context.correlationId,                durationMs = (System.nanoTime() - startNanos) / 1_000_000,            )        }    }    /**     * Search using DuckDuckGo Instant Answer API.     *     * Returns a list of [SearchResult] with title, snippet, and URL.     * If the API returns no instant answers, falls back to related topics.     */    private suspend fun searchDuckDuckGo(        query: String,        context: BrainContext,    ): List<SearchResult> = withContext(Dispatchers.IO) {        val encodedQuery = java.net.URLEncoder.encode(query, "UTF-8")        val url = "https://api.duckduckgo.com/?q=$encodedQuery&format=json&no_html=1&skip_disambig=1"        val request = Request.Builder()            .url(url)            .header("User-Agent", "NOUS/1.0 (Android; AI Assistant)")            .get()            .build()        val response = httpClient.newCall(request).execute()        val body = response.body?.string() ?: return@withContext emptyList()        if (!response.isSuccessful) {            Timber.w("DuckDuckGo API returned HTTP %d", response.code)            return@withContext emptyList()        }        val json = JSONObject(body)        val results = mutableListOf<SearchResult>()        // 1. Abstract (main answer)        val abstractText = json.optString("AbstractText", "")        val abstractSource = json.optString("AbstractSource", "")        val abstractUrl = json.optString("AbstractURL", "")        if (abstractText.isNotEmpty()) {            results.add(SearchResult(                title = abstractSource.ifEmpty { "Instant Answer" },                snippet = abstractText,                url = abstractUrl,            ))        }        // 2. Related topics (each has text + first URL)        val topics = json.optJSONArray("RelatedTopics") ?: JSONArray()        for (i in 0 until minOf(topics.length(), MAX_RESULTS)) {            val topic = topics.optJSONObject(i) ?: continue            val text = topic.optString("Text", "")            val firstUrl = topic.optString("FirstURL", "")            if (text.isNotEmpty()) {                results.add(SearchResult(                    title = text.substringBefore(" -", text.take(80)),                    snippet = text,                    url = firstUrl,                ))            }        }        results    }    data class SearchResult(        val title: String,        val snippet: String,        val url: String,    )    companion object {        private const val MAX_RESULTS = 5    }}/** * NOUS — Fetch URL Tool (Module 11 Connectivity → Agentic Tool). * * Strategy §11 + Table 3: Implements the [AgenticTool] interface for URL fetching. * Replaces Brain's placeholder FetchUrlTool (which returned "not yet implemented"). * * Fetches a web page via HTTP and extracts the text content. Uses OkHttp for * the HTTP request and a simple HTML-to-text converter (strips tags, scripts, * styles, and extracts paragraph text). * * ## Security * * Only HTTPS URLs are allowed. HTTP URLs are rejected with a clear error. * Redirects are followed (up to 5). Response size is capped at 1MB to prevent * memory exhaustion from large pages. * * @see <a href="docs/strategy/NOUS-Strategy-2-14-extracted.txt">§11 Connectivity + Table 3 FetchUrlTool</a> */@Singletonclass FetchUrlTool @Inject constructor(    private val httpClient: OkHttpClient,) : AgenticTool {    override val id: String = "fetch_url"    override val displayName: String = "Fetch URL"    override val description: String =        "Fetch a web page and return its text content. Use after search_web to read a specific result."    override val paramSchema: List<ToolParam> = listOf(        ToolParam(            name = "url",            description = "The URL to fetch (must be HTTPS)",            required = true,            example = "https://example.com/article",        ),    )    override val requiresNetwork: Boolean = true    override suspend fun execute(        params: Map<String, String>,        context: BrainContext,    ): AgenticStepResult {        val startNanos = System.nanoTime()        val url = params["url"] ?: return AgenticStepResult.ToolFailure(            toolId = id,            error = "Missing required parameter: url",            retryable = false,            correlationId = context.correlationId,            durationMs = 0L,        )        // Security: only HTTPS allowed.        if (!url.startsWith("https://", ignoreCase = true)) {            return AgenticStepResult.ToolFailure(                toolId = id,                error = "Only HTTPS URLs are allowed for security. Got: $url",                retryable = false,                correlationId = context.correlationId,                durationMs = (System.nanoTime() - startNanos) / 1_000_000,            )        }        return try {            val text = fetchAndExtractText(url)            val truncated = if (text.length > MAX_TEXT_LENGTH) {                text.take(MAX_TEXT_LENGTH) + "\n\n[... truncated, ${text.length - MAX_TEXT_LENGTH} more chars]"            } else {                text            }            AgenticStepResult.ToolSuccess(                toolId = id,                output = "Content from $url:\n\n$truncated",                data = mapOf("url" to url, "contentLength" to text.length),                correlationId = context.correlationId,                durationMs = (System.nanoTime() - startNanos) / 1_000_000,            )        } catch (e: Exception) {            Timber.e(e, "URL fetch failed: %s", url)            AgenticStepResult.ToolFailure(                toolId = id,                error = "Fetch failed: ${e.message}",                retryable = true,                correlationId = context.correlationId,                durationMs = (System.nanoTime() - startNanos) / 1_000_000,            )        }    }    /**     * Fetch URL and extract text content.     *     * Strips HTML tags, scripts, styles, and extracts text from paragraphs.     * Caps response at 1MB to prevent memory exhaustion.     */    private suspend fun fetchAndExtractText(url: String): String = withContext(Dispatchers.IO) {        val request = Request.Builder()            .url(url)            .header("User-Agent", "NOUS/1.0 (Android; AI Assistant)")            .header("Accept", "text/html, text/plain, */*")            .get()            .build()        val response = httpClient.newCall(request).execute()        if (!response.isSuccessful) {            throw RuntimeException("HTTP ${response.code}: ${response.message}")        }        val contentType = response.header("Content-Type", "") ?: ""        val body = response.body?.string()?.take(MAX_RESPONSE_BYTES)            ?: throw RuntimeException("Empty response body")        // If plain text, return as-is.        if (contentType.contains("text/plain", ignoreCase = true)) {            return@withContext body        }        // If HTML, extract text.        extractTextFromHtml(body)    }    /**     * Simple HTML-to-text converter.     *     * Removes <script>, <style>, <head> blocks entirely.     * Converts <p>, <br>, <div> to newlines.     * Strips remaining HTML tags.     * Collapses excessive whitespace.     */    private fun extractTextFromHtml(html: String): String {        var text = html        // Remove script, style, head, nav, footer blocks entirely.        text = text.replace(Regex("(?is)<(script|style|head|nav|footer)[^>]*>.*?</\\1>", RegexOption.IGNORE_CASE), "")        // Remove all remaining HTML tags.        text = text.replace(Regex("(?s)<[^>]+>"), " ")        // Decode common HTML entities.        text = text            .replace("&amp;", "&")            .replace("&lt;", "<")            .replace("&gt;", ">")            .replace("&quot;", "\"")            .replace("&#39;", "'")            .replace("&nbsp;", " ")            .replace("&mdash;", "—")            .replace("&ndash;", "–")        // Collapse whitespace.        text = text.replace(Regex("[ \\t]+"), " ")        text = text.replace(Regex("\\n\\s*\\n+"), "\n\n")        text = text.trim()        return text    }    companion object {        private const val MAX_TEXT_LENGTH = 8000        private const val MAX_RESPONSE_BYTES = 1_048_576  // 1MB    }}/** * Hilt module that registers [WebSearchTool] + [FetchUrlTool] into the * Brain's [AgenticToolRegistry] via multibinding. * * Strategy §14.3: Feature modules register agentic tools via Hilt multibinding. * This is the real implementation — replaces Brain's placeholder tools that * returned "not yet implemented". */@Module@InstallIn(SingletonComponent::class)object ConnectivityToolsModule {    /**     * Dedicated OkHttpClient for connectivity tools (web search + fetch).     *     * Uses a custom qualifier so it does NOT collide with the LLM module's     * OkHttpClient binding in the Hilt graph.     */    @Provides    @Singleton    @com.roshan.persona.connectivity.di.ConnectivityHttp    fun provideConnectivityOkHttpClient(): OkHttpClient {        return OkHttpClient.Builder()            .connectTimeout(15, TimeUnit.SECONDS)            .readTimeout(30, TimeUnit.SECONDS)            .followRedirects(true)            .build()    }    @Provides    @Singleton    fun provideWebSearchTool(        @com.roshan.persona.connectivity.di.ConnectivityHttp client: OkHttpClient,    ): WebSearchTool = WebSearchTool(client)    @Provides    @Singleton    fun provideFetchUrlTool(        @com.roshan.persona.connectivity.di.ConnectivityHttp client: OkHttpClient,    ): FetchUrlTool = FetchUrlTool(client)    @Provides    @IntoSet    fun bindWebSearchTool(tool: WebSearchTool): AgenticTool = tool    @Provides    @IntoSet    fun bindFetchUrlTool(tool: FetchUrlTool): AgenticTool = tool}